#!/usr/bin/env node
import { writeFileSync, mkdirSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { BASE_PATH } from '../story.config.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const outPath = join(__dirname, '../static/_redirects');

const lines = [
	'# Generated by scripts/write-redirects.mjs from story.config.js. Do not edit.',
	`${BASE_PATH}/* /:splat 200`,
	'/* /404.html 200',
	''
];

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, lines.join('\n'));
console.log(`Wrote static/_redirects: ${BASE_PATH}/* self-alias and SPA fallback`);
